module ActionController;module UrlFor;extend ActiveSupport::Concern;include AbstractController::UrlFor;def initialize(...)super ;@_url_options=nil;end;def url_options;@_url_options||={host:request.host,port:request.optional_port,protocol:request.protocol,_recall:request.path_parameters}.merge!(super ).freeze;if(same_origin=_routes.equal?(request.routes))||(script_name=request.engine_script_name(_routes))||(original_script_name=request.original_script_name);options=@_url_options.dup;if original_script_name;options[:original_script_name]=original_script_name;else if same_origin;options[:script_name]=request.script_name.empty?? "": request.script_name.dup;else options[:script_name]=script_name;end;end;options.freeze;else @_url_options;end;end;end;end
